pub unsafe fn OptimizeHuffmanForRle(
    mut length: c_int,
    mut counts: *mut size_t,
) {
    let mut i: c_int = 0;
    let mut k: c_int = 0;
    let mut stride: c_int = 0;
    let mut symbol: size_t = 0;
    let mut sum: size_t = 0;
    let mut limit: size_t = 0;
    let mut good_for_rle: *mut c_int = ::core::ptr::null_mut::<c_int>();
    while length >= 0 as c_int {
        if length == 0 as c_int {
            return;
        }
        if *counts.offset((length - 1 as c_int) as isize) != 0 as size_t {
            break;
        }
        length -= 1;
    }
    good_for_rle = malloc(
        (length as c_uint as size_t)
            .wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
    ) as *mut c_int;
    i = 0 as c_int;
    while i < length {
        *good_for_rle.offset(i as isize) = 0 as c_int;
        i += 1;
    }
    symbol = *counts.offset(0 as c_int as isize);
    stride = 0 as c_int;
    i = 0 as c_int;
    while i < length + 1 as c_int {
        if i == length || *counts.offset(i as isize) != symbol {
            if symbol == 0 as size_t && stride >= 5 as c_int
                || symbol != 0 as size_t && stride >= 7 as c_int
            {
                k = 0 as c_int;
                while k < stride {
                    *good_for_rle.offset((i - k - 1 as c_int) as isize) =
                        1 as c_int;
                    k += 1;
                }
            }
            stride = 1 as c_int;
            if i != length {
                symbol = *counts.offset(i as isize);
            }
        } else {
            stride += 1;
        }
        i += 1;
    }
    stride = 0 as c_int;
    limit = *counts.offset(0 as c_int as isize);
    sum = 0 as size_t;
    i = 0 as c_int;
    while i < length + 1 as c_int {
        if i == length
            || *good_for_rle.offset(i as isize) != 0
            || AbsDiff(*counts.offset(i as isize), limit) >= 4 as size_t
        {
            if stride >= 4 as c_int
                || stride >= 3 as c_int && sum == 0 as size_t
            {
                let mut count: c_int =
                    sum.wrapping_add((stride / 2 as c_int) as size_t)
                        .wrapping_div(stride as size_t) as c_int;
                if count < 1 as c_int {
                    count = 1 as c_int;
                }
                if sum == 0 as size_t {
                    count = 0 as c_int;
                }
                k = 0 as c_int;
                while k < stride {
                    *counts.offset((i - k - 1 as c_int) as isize) = count as size_t;
                    k += 1;
                }
            }
            stride = 0 as c_int;
            sum = 0 as size_t;
            if i < length - 3 as c_int {
                limit = (*counts.offset(i as isize))
                    .wrapping_add(*counts.offset((i + 1 as c_int) as isize))
                    .wrapping_add(*counts.offset((i + 2 as c_int) as isize))
                    .wrapping_add(*counts.offset((i + 3 as c_int) as isize))
                    .wrapping_add(2 as size_t)
                    .wrapping_div(4 as size_t);
            } else if i < length {
                limit = *counts.offset(i as isize);
            } else {
                limit = 0 as size_t;
            }
        }
        stride += 1;
        if i != length {
            sum = sum.wrapping_add(*counts.offset(i as isize));
        }
        i += 1;
    }
    free(good_for_rle as *mut c_void);
}
